import com.surprising.aeron.client.SurprisingAeronClient;
import com.surprising.aeron.protocol.*;
import com.surprising.product.api.ProductLine;
import java.time.Duration;
import java.util.List;
import java.util.UUID;

class InsuranceGate {
    final ProductLine line = ProductLine.requireExternalCode(System.getProperty("surprising.aeron.product-line"));
    final String asset = line == ProductLine.INVERSE_PERPETUAL ? "BTC" : "USDT";
    final long seed = 61001;
    final long source = 962001;
    final SurprisingAeronClient client;
    long sequence = System.currentTimeMillis();
    InsuranceGate(SurprisingAeronClient client) { this.client = client; }
    long user(int offset) { return 10_000_000_000L + seed * 10 + offset; }
    CoreResponse command(CoreMessageType type, long user, byte[] data) {
        return client.submit(new CoreMessage(CoreMessageHeader.command(type, UUID.randomUUID(), line,
                CommandSource.OPERATIONS, source, ++sequence, user, sequence, sequence), data));
    }
    void applied(CoreMessageType type, long user, byte[] data) {
        var r=command(type,user,data);
        if(r.commandStatus()!=ResponseStatus.APPLIED) throw new AssertionError(type+" "+r.resultCode());
    }
    byte[] query(CoreMessageType type,long user,byte[] data) {
        var r=client.submit(new CoreMessage(CoreMessageHeader.query(type,UUID.randomUUID(),line,
                CommandSource.OPERATIONS,source,0,user,++sequence,sequence),data));
        if(r.status()!=ResponseStatus.OK) throw new AssertionError(type+" "+r.resultCode());
        return r.data();
    }
    CoreLiquidationWorkView work(CoreLiquidationWorkView.Purpose purpose) {
        return CoreLiquidationWorkCodec.decodeWork(query(CoreMessageType.LIQUIDATION_WORK_QUERY,0,
                CoreLiquidationWorkCodec.encodeQuery(line,purpose,0,100,1_048_576)));
    }
    CoreLiquidationWorkView.Resolution target(CoreLiquidationWorkView.Purpose purpose) {
        return work(purpose).resolutions().stream().filter(r->r.userId()==user(4)).findFirst().orElseThrow();
    }
    void execute() {
        var before=target(CoreLiquidationWorkView.Purpose.INSURANCE);
        long openingInsurance=line==ProductLine.INVERSE_PERPETUAL?179:178;
        long expectedDeficit=line==ProductLine.INVERSE_PERPETUAL?121:22;
        var treasury=CoreStateQueryCodec.decodeTreasuryState(query(CoreMessageType.TREASURY_STATE_QUERY,0,new byte[0])).stream()
                .filter(t->t.asset().equals(asset)).findFirst().orElseThrow();
        if(treasury.insuranceBalanceUnits()!=openingInsurance || before.deficitUnits()!=expectedDeficit
                || before.recommendedCoveredUnits()!=expectedDeficit) throw new AssertionError("opening insurance fixture: "+treasury+" "+before);
        applied(CoreMessageType.ADJUST_INSURANCE_FUND,0,TradingCommandCodec.encodeAdjustInsuranceFund(new AdjustInsuranceFundCommand(asset,1-openingInsurance)));
        var funded=target(CoreLiquidationWorkView.Purpose.INSURANCE);
        if(funded.recommendedCoveredUnits()!=1) throw new AssertionError("expected coverage=1");
        var invalid=command(CoreMessageType.RESOLVE_LIQUIDATION,user(4),TradingCommandCodec.encodeResolveLiquidation(
                new ResolveLiquidationCommand(before.liquidationId(),ResolveLiquidationCommand.Resolution.INSURANCE,2)));
        if(invalid.commandStatus()!=ResponseStatus.REJECTED || !invalid.resultCode().name().equals("INSURANCE_ALLOCATION_MISMATCH"))
            throw new AssertionError("overclaim must reject: "+invalid.resultCode());
        if(!target(CoreLiquidationWorkView.Purpose.INSURANCE).equals(funded)) throw new AssertionError("rejection changed work");
        applied(CoreMessageType.RESOLVE_LIQUIDATION,user(4),TradingCommandCodec.encodeResolveLiquidation(
                new ResolveLiquidationCommand(before.liquidationId(),ResolveLiquidationCommand.Resolution.INSURANCE,1)));
        var after=target(CoreLiquidationWorkView.Purpose.ADL);
        if(after.deficitUnits()!=before.deficitUnits()-1) throw new AssertionError("deficit must decrease exactly 1");
    }
    void verify() {
        if(work(CoreLiquidationWorkView.Purpose.INSURANCE).resolutions().stream().anyMatch(r->r.userId()==user(4)))
            throw new AssertionError("insurance work still pending");
        var adl=target(CoreLiquidationWorkView.Purpose.ADL);
        if(adl.recommendedCoveredUnits()!=0 || adl.deficitUnits()<=0) throw new AssertionError("ADL work");
        long total=economicFunds();
        long expected=line==ProductLine.INVERSE_PERPETUAL?2182:2183;
        if(total!=expected) throw new AssertionError("funds expected"+expected+" actual"+total);
        System.out.println("INSURANCE_GATE_PASS product="+line+" covered=1 overclaimRejected=true remainingDeficit="+adl.deficitUnits()+" fundsDifference=0");
    }
    long economicFunds() {
        long total=0;
        for(int i=1;i<=4;i++) {
            var u=CoreStateQueryCodec.decodeUserState(query(CoreMessageType.USER_STATE_QUERY,user(i),new byte[0]));
            for(var b:u.balances()) if(b.asset().equals(asset)) total=Math.addExact(total,Math.addExact(b.availableUnits(),b.lockedUnits()));
            if(i==4 && u.positions().stream().anyMatch(p->p.signedQuantitySteps()!=0)) throw new AssertionError("liquidated position");
        }
        for(var t:CoreStateQueryCodec.decodeTreasuryState(query(CoreMessageType.TREASURY_STATE_QUERY,0,new byte[0]))) if(t.asset().equals(asset)) {
            if(t.insuranceBalanceUnits()!=0) throw new AssertionError("insurance budget not consumed");
            total=Math.addExact(total,t.feeBalanceUnits()); total=Math.addExact(total,t.insuranceBalanceUnits());
            total=Math.subtractExact(total,t.insuranceDeficitUnits()); total=Math.addExact(total,t.liquidationFeeBalanceUnits());
            total=Math.addExact(total,t.fundingResidualBalanceUnits()); total=Math.addExact(total,t.roundingResidualBalanceUnits());
            total=Math.addExact(total,t.clearingPnlBalanceUnits());
        }
        return total;
    }
    public static void main(String[] args) {
        try(var client=SurprisingAeronClient.connect(ProductLine.requireExternalCode(System.getProperty("surprising.aeron.product-line")),
                List.of("127.0.0.1"),"127.0.0.1",Duration.ofSeconds(10))) {
            var gate=new InsuranceGate(client);
            if(System.getProperty("round67.insurance-mode","").equals("inspect")) {
                System.out.println(gate.work(CoreLiquidationWorkView.Purpose.INSURANCE));
                System.out.println(CoreStateQueryCodec.decodeTreasuryState(gate.query(CoreMessageType.TREASURY_STATE_QUERY,0,new byte[0])));
                return;
            }
            if(!System.getProperty("round67.insurance-mode","execute").equals("verify")) gate.execute();
            gate.verify();
        }
    }
}

